MAX_READ_BYTES = 4 * 1024 * 1024


def canonical_uuid(value):
    if not isinstance(value, str) or str(UUID(value)) != value:
        raise ValueError("canonical UUID identity required")
    return value


def artifact_references(payload):
    """Exact Artifact citations in the scientific payload, excluding producer stamps."""
    found = set()

    def visit(value):
        if isinstance(value, dict):
            if set(value) == set(ExactReference.model_fields):
                ref = ExactReference.model_validate(value)
                if ref.authority == "artifact-platform":
                    found.add(ref)
                return
            for child in value.values():
                visit(child)
        elif isinstance(value, list):
            for child in value:
                visit(child)

    visit(payload.model_dump(mode="json"))
    return tuple(sorted(found, key=canonical_bytes))


