class WorkspaceArtifactEvidence(Contract):
    schema_version: Literal["forge.workspace-artifact-evidence.v1"] = (
        "forge.workspace-artifact-evidence.v1"
    )
    mode: Literal["byte_access_only"] = "byte_access_only"
