    operation_id: Identifier
    operation_digest_sha256: Digest
    reads: tuple[ArtifactReadEvidence, ...] = Field(min_length=1, max_length=1024)
    snapshot_revisions: tuple[RevisionReference, ...] = Field(
        default=(), max_length=1024
    )

    @model_validator(mode="after")
    def unique_pins(self):
        canonical_uuid(self.scope.organization_id)
        canonical_uuid(self.scope.project_id)
        references = tuple(read.reference for read in self.reads)
        if references != tuple(sorted(set(references), key=canonical_bytes)):
            raise ValueError("verified Artifact reads must be unique and sorted")
        identities = [
            (ref.reference.record_id, ref.reference.revision)
            for ref in self.snapshot_revisions
        ]
        if len(identities) != len(set(identities)):
            raise ValueError("canonical snapshot revisions must be unique")
        return self

    def require_intent(self, principal, operation):
        if (
            principal.subject_kind != "human"
            or principal.required_scope != "forge:write"
        ):
            raise ForgeError("forbidden", "original human scientific writer required")
        canonical_uuid(principal.subject_id)
        canonical_uuid(principal.credential_id)
        if (
            principal.organization_id != operation.scope.organization_id
            or operation.producer.authority != "human"
            or operation.producer.subject_id != principal.subject_id
            or self.scope != operation.scope
            or self.operation_id != operation.operation_id
            or self.operation_digest_sha256 != operation.payload_digest_sha256
            or tuple(read.reference for read in self.reads)
            != artifact_references(operation.payload)
        ):
            raise ForgeError(
                "reference_conflict",
                "Artifact evidence differs from exact scientific intent",
            )
        if isinstance(operation.payload, Artifact):
            artifact = operation.payload
            observed = next(
                (item for item in self.reads if item.reference == artifact.object), None
            )
            if (
                observed is None
                or observed.reference.kind != "object"
                or observed.manifest != artifact.manifest
                or observed.byte_count != artifact.byte_count
                or observed.media_type != artifact.media_type
                or artifact.delivery is not None
                and (
                    str(artifact.delivery.publication_id)
                    != observed.reference.record_id
                    or artifact.delivery.logical_path != observed.logical_path
                )
            ):
                raise ForgeError(
                    "reference_conflict",
                    "Artifact declaration differs from its actual manifest and bytes",
                )
        if isinstance(operation.payload, Snapshot):
            if operation.payload.capture_completeness != "partial":
                raise ForgeError(
                    "capture_evidence_required",
                    "byte reads do not prove complete capture",
                )
            expected = {
                ref for ref in operation.payload.sources if ref.authority == "forge"
            }
            if (
                not self.snapshot_revisions
                or {pin.reference for pin in self.snapshot_revisions} != expected
            ):
                raise ForgeError(
                    "reference_conflict", "snapshot revision evidence is incomplete"
                )
        elif self.snapshot_revisions:
            raise ForgeError(
                "reference_conflict", "non-snapshot intent has snapshot evidence"
            )


