def sign_artifact_request(key, action, digest, *, now_ms=None):
    if len(key) < 32:
        raise ForgeError("authority_unavailable", "workspace proof key is unavailable")
    now_ms = time_ns() // 1_000_000 if now_ms is None else now_ms
    values = {
        "schema_version": AUTHORIZATION_SCHEMA,
        "action": action,
        "request_digest_sha256": digest,
        "nonce": uuid4().hex,
        "issued_unix_ms": now_ms,
        "expires_unix_ms": now_ms + MAX_LIFETIME_MS,
    }
    signature = hmac.new(key, canonical_bytes(values), hashlib.sha256).hexdigest()
    return WorkspaceArtifactAuthorization.model_validate({**values, "signature_sha256": signature})


def verify_artifact_request(key, proof, action, digest, *, now_ms=None):
    proof = WorkspaceArtifactAuthorization.model_validate_json(proof.model_dump_json())
    now_ms = time_ns() // 1_000_000 if now_ms is None else now_ms
    if (
        len(key) < 32
        or proof.action != action
        or proof.request_digest_sha256 != digest
        or not proof.issued_unix_ms < proof.expires_unix_ms
        or proof.expires_unix_ms - proof.issued_unix_ms > MAX_LIFETIME_MS
        or proof.issued_unix_ms > now_ms + MAX_FUTURE_SKEW_MS
        or proof.expires_unix_ms <= now_ms
    ):
        raise ForgeError(
            "forbidden", "workspace Artifact request proof differs or expired"
        )
    expected = hmac.new(
        key,
        canonical_bytes(proof.model_dump(mode="json", exclude={"signature_sha256"})),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected, proof.signature_sha256):
        raise ForgeError("forbidden", "workspace Artifact request signature differs")


